-- 0002_add_status.up.sql
-- Add orders.status with batched backfill, per review rules.

SET lock_timeout = '500ms';
SET statement_timeout = '700ms';

-- 1. Add column with constant default. In PG 11+ this is a metadata-only change:
-- no table rewrite, no long lock, all existing rows read as 'placed'.
ALTER TABLE orders ADD COLUMN status text NOT NULL DEFAULT 'placed';

-- 2. Backfill non-'placed' values in primary-key batches, each batch its own transaction.
CREATE OR REPLACE PROCEDURE backfill_order_status()
LANGUAGE plpgsql
AS $$
DECLARE
    batch_size CONSTANT int := 10000;
    min_id bigint;
    max_id bigint;
    current_min bigint;
    current_max bigint;
BEGIN
    SELECT min(id), max(id) INTO min_id, max_id FROM orders;
    current_min := min_id;

    WHILE current_min <= max_id LOOP
        current_max := current_min + batch_size - 1;

        UPDATE orders
        SET status = CASE
            WHEN cancelled_at IS NOT NULL THEN 'cancelled'
            WHEN refunded_cents > 0 AND refunded_cents >= total_cents THEN 'refunded'
            WHEN refunded_cents > 0 THEN 'partly_refunded'
            WHEN shipped_at IS NOT NULL THEN 'shipped'
            ELSE 'placed'
        END
        WHERE id >= current_min
          AND id <= current_max
          AND status = 'placed'
          AND (
              cancelled_at IS NOT NULL
              OR refunded_cents > 0
              OR shipped_at IS NOT NULL
          );

        current_min := current_max + 1;
        COMMIT;
    END LOOP;
END;
$$;

CALL backfill_order_status();

DROP PROCEDURE backfill_order_status();

