ALTER TABLE orders ADD CONSTRAINT orders_status_check
CHECK (status IN ('cancelled', 'refunded', 'partly_refunded', 'shipped', 'placed')) NOT VALID;

-- 4. Validate constraint under SHARE UPDATE EXCLUSIVE (does not block reads/writes).
ALTER TABLE orders VALIDATE CONSTRAINT orders_status_check;

-- 5. Column is already NOT NULL; drop the now-unneeded default.
ALTER TABLE orders ALTER COLUMN status DROP DEFAULT;

